class Solution {
public:
    int connectSticks(vector<int>& sticks) {
        priority_queue<int, vector<int>, greater<int>> pq(
            sticks.begin(), sticks.end());
        int total = 0;
        while (pq.size() > 1) {
            int a = pq.top();
            pq.pop();
            int b = pq.top();
            pq.pop();
            total += a + b;
            pq.push(a + b);
        }
        return total;
    }
};
